import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"Agnes AI","description":"Agnes AI 免费多模态 API：官网入口、Free Access 获取 Key、文本/图片/视频模型列表，以及在 MiniTavern 中的填法。","frontmatter":{"title":"Agnes AI","description":"Agnes AI 免费多模态 API：官网入口、Free Access 获取 Key、文本/图片/视频模型列表，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"Agnes AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Agnes AI 免费多模态 API：官网入口、Free Access 获取 Key、文本/图片/视频模型列表，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/free-cloud/agnes-ai"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/free-cloud/agnes-ai"}]]},"headers":[],"relativePath":"free-cloud/agnes-ai.md","filePath":"free-cloud/agnes-ai.md","lastUpdated":1787215934000}'),n={name:"free-cloud/agnes-ai.md"};function d(s,e,i,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h1><p>新加坡 Sapiens AI 旗下的多模态模型服务：同一套 OpenAI 兼容网关覆盖<strong>文本对话、生图、视频</strong>。提供 <strong>Free Access（免费试用档）</strong>，适合无付费 Key 时开聊与试生图；额度与限速以控制台为准。</p><h2 id="官网与入口" tabindex="-1">官网与入口 <a class="header-anchor" href="#官网与入口" aria-label="Permalink to &quot;官网与入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>地址</th></tr></thead><tbody><tr><td>国际站</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a></td></tr><tr><td>中国站</td><td><a href="https://agnes-ai.cn/" target="_blank" rel="noreferrer">agnes-ai.cn</a></td></tr><tr><td>API 控制台（注册 / Key）</td><td><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>开发者文档</td><td><a href="https://agnes-ai.com/en/docs/overview" target="_blank" rel="noreferrer">agnes-ai.com/en/docs/overview</a></td></tr><tr><td>模型目录（GitHub）</td><td><a href="https://github.com/AgnesAI-Labs/AgnesAI-Models" target="_blank" rel="noreferrer">AgnesAI-Labs/AgnesAI-Models</a></td></tr><tr><td>API Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr></tbody></table><p>按地区选国际站或中国站即可；<strong>API Key 与 Base URL 以控制台 / 文档当前显示为准</strong>。</p><h2 id="免费怎么获取-free-access" tabindex="-1">免费怎么获取（Free Access） <a class="header-anchor" href="#免费怎么获取-free-access" aria-label="Permalink to &quot;免费怎么获取（Free Access）&quot;">​</a></h2><ol><li>打开 <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a> 注册并登录（常见为邮箱注册；是否要绑卡以页面为准）。</li><li>进入开发者控制台 → <strong>API Keys</strong> → 创建并复制 Key（一般以 <code>sk-</code> 开头）。</li><li>在 MiniTavern 用 <strong>自定义 (OpenAI)</strong>（聊天）或 <strong>自定义 (OpenAI Images)</strong>（生图）填入 Base URL 与 Key，见下文。</li></ol><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>免费方式</td><td><strong>Free Access</strong>：核心 Flash 系列可免费调用（有 RPM / fair-use 限速），适合个人试用与 demo</td></tr><tr><td>付费升级</td><td><strong>Token Plan</strong>：更高 TPS / 月额度，面向生产与高频 Agent（非必须）</td></tr><tr><td>限速参考（免费档）</td><td>文本约 <strong>20 RPM</strong>；生图按分辨率（1K 约 20 RPM，越高越严）；视频约 <strong>1 RPM</strong>（官方 <a href="https://agnes-ai.com/en/docs/tokenplan" target="_blank" rel="noreferrer">Token Plan FAQ</a>）</td></tr><tr><td>绑卡</td><td>Free Access 通常不强制；正式商用或更高限额再考虑 Token Plan</td></tr></tbody></table><blockquote><p>政策会调整。若控制台显示某模型需 Token Plan，或返回 429，以官网与账户权限为准。</p></blockquote><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>下列为公开文档与模型目录中的常见 ID（<strong>大小写敏感</strong>）。Flash 多为免费档；带 <strong>Pro</strong> 的一般为付费推理模型。</p><h3 id="文本-对话-视觉理解" tabindex="-1">文本（对话 / 视觉理解） <a class="header-anchor" href="#文本-对话-视觉理解" aria-label="Permalink to &quot;文本（对话 / 视觉理解）&quot;">​</a></h3><p>走 Chat Completions：<code>POST /v1/chat/completions</code>。在 MiniTavern 选 <strong>自定义 (OpenAI)</strong>。</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>agnes-2.5-flash</code></td><td>推荐：对话、编码、工具调用、多轮与图像理解；上下文约 512K</td></tr><tr><td><code>agnes-2.0-flash</code></td><td>上一代 Flash，兼容备用</td></tr><tr><td><code>agnes-2.5-pro</code> / <code>agnes-2.5-pro-alpha</code></td><td>付费推理档（高级编码 / 科学推理等），<strong>勿当免费档</strong></td></tr></tbody></table><h3 id="图片-文生图-图生图" tabindex="-1">图片（文生图 / 图生图） <a class="header-anchor" href="#图片-文生图-图生图" aria-label="Permalink to &quot;图片（文生图 / 图生图）&quot;">​</a></h3><p>走 Images：文生图与图生图均为 <code>POST /v1/images/generations</code>（图生图在 body 里带 <code>image</code>，<strong>不是</strong> OpenAI 的 <code>/images/edits</code>）。在 MiniTavern 选 <strong>自定义 (OpenAI Images)</strong>，Base URL 同为 <code>https://apihub.agnes-ai.com/v1</code>；App 对自定义协议会按此路由，测连带参考图也会打 generations。</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>agnes-image-2.1-flash</code></td><td>推荐：高信息密度生图与编辑，灵活尺寸</td></tr><tr><td><code>agnes-image-2.0-flash</code></td><td>文生图 / 图生图，URL 或 Base64 输出</td></tr></tbody></table><h3 id="视频-文生视频-图生视频" tabindex="-1">视频（文生视频 / 图生视频） <a class="header-anchor" href="#视频-文生视频-图生视频" aria-label="Permalink to &quot;视频（文生视频 / 图生视频）&quot;">​</a></h3><p>走 Videos：<code>POST /v1/videos</code>（异步任务）。常见 ID：</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>agnes-video-v2.0</code></td><td>文生视频、图生视频、多图/关键帧等</td></tr><tr><td><code>agnes-video-v2.5</code>（或文档中的 Video 2.5）</td><td>新一代视频接口，以<a href="https://agnes-ai.com/en/docs/agnes-video-v20" target="_blank" rel="noreferrer">官方视频文档</a>为准</td></tr></tbody></table><p>MiniTavern <strong>当前无内置视频生成入口</strong>；上表便于对照官网能力。聊天与生图可先用 Flash 文本 / 图像模型。</p><h2 id="在-minitavern-里怎么填" tabindex="-1">在 MiniTavern 里怎么填 <a class="header-anchor" href="#在-minitavern-里怎么填" aria-label="Permalink to &quot;在 MiniTavern 里怎么填&quot;">​</a></h2><p>通用步骤见 <a href="/ultra_guides/manual/model-link">模型连接</a>。</p><h3 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h3><p>路径：<strong>设置 → 模型 → 模型连接 → 新建</strong></p><ol><li>平台选 <strong>自定义 (OpenAI)</strong></li><li>Base URL：<code>https://apihub.agnes-ai.com/v1</code></li><li>粘贴 API Key</li><li>模型 ID 填 <code>agnes-2.5-flash</code>（或控制台列表中的其它文本模型）</li><li><strong>测试</strong> → 成功后设为默认</li></ol><h3 id="生图" tabindex="-1">生图 <a class="header-anchor" href="#生图" aria-label="Permalink to &quot;生图&quot;">​</a></h3><p>路径：<strong>设置 → 生图 → 生图连接</strong></p><ol><li>平台选 <strong>自定义 (OpenAI Images)</strong></li><li>Base URL 同上</li><li>同一 Key；模型填 <code>agnes-image-2.1-flash</code> 等</li><li>测连后再用于 <code>/imagine</code> 或生图入口</li></ol><p>聊天连接与生图连接可分开：例如聊天用 <code>agnes-2.5-flash</code>，生图用 <code>agnes-image-2.1-flash</code>。</p><h2 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h2><ul><li><a href="/ultra_guides/free-cloud/">免费云端总览</a> — 其它厂商免费 / 试用额度</li><li><a href="/ultra_guides/free-cloud/#免费生图怎么配">免费生图</a></li><li><a href="/ultra_guides/manual/model-link">模型连接</a></li><li><a href="/ultra_guides/local/image-gen/">生图模型部署</a> — 本机 A1111 / ComfyUI</li></ul>',32)])])}const A=t(n,[["render",d]]);export{p as __pageData,A as default};
